solution.solution.cpp:
#include <cstddef>

class Buffer
{
public:
    explicit Buffer(std::size_t size) : m_data{ new int[size]{} }, m_size{ size } {}
    ~Buffer() { delete[] m_data; }

    Buffer(const Buffer& other) : m_data{ new int[other.m_size] }, m_size{ other.m_size }
    {
        for (std::size_t i{ 0 }; i < m_size; ++i)
        {
            m_data[i] = other.m_data[i];
        }
    }

    Buffer& operator=(const Buffer&) = delete;

    int& operator[](std::size_t i) { return m_data[i]; }
    const int& operator[](std::size_t i) const { return m_data[i]; }
    std::size_t size() const { return m_size; }
    const int* data() const { return m_data; }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
};

unitTests:
TEST("the copy has the same contents") { Buffer a{ 3 }; a[0] = 1; a[1] = 2; a[2] = 3; const Buffer b{ a }; CHECK_EQ(b.size(), 3u); CHECK_EQ(b[0], 1); CHECK_EQ(b[2], 3); }
TEST("the copy has its own memory") { Buffer a{ 2 }; Buffer b{ a }; CHECK(a.data() != b.data()); b[0] = 99; CHECK_EQ(a[0], 0); }
TEST("no leaks, no double free") { CHECK_NO_LEAK(Buffer a{ 50 }; Buffer b{ a }; Buffer c{ b }); }

